<?php

# @autogenerated
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\PlatformIdentity\Domain\ValueObject\PlatformIdentityTrustedClientVO;
use Civi\Lughauth\Features\Access\TrustedClient\Domain\TrustedClientRef;

final class PlatformIdentityTrustedClientVOUnitTest extends TestCase
{
    public function test_asignation_keep_value(): void
    {
        $value = new TrustedClientRef('one');
        $ref = PlatformIdentityTrustedClientVO::from($value);
        $this->assertEquals(new TrustedClientRef('one'), $ref->value());
        $other = PlatformIdentityTrustedClientVO::tryFrom($ref, new ConstraintFailList());
        $this->assertSame($other, $ref);
        $more = PlatformIdentityTrustedClientVO::from($ref);
        $this->assertSame($more, $ref);
    }
    public function test_asignation_invalid_type(): void
    {
        $errors = new ConstraintFailList();
        $other = PlatformIdentityTrustedClientVO::tryFrom('1', $errors);
        $this->assertNull($other);
        $this->assertTrue($errors->hasErrors());
    }
    public function test_empty(): void
    {
        $ref = PlatformIdentityTrustedClientVO::empty();
        $this->assertNull($ref->value());
    }
    public function test_try_from_empty(): void
    {
        $ref = PlatformIdentityTrustedClientVO::tryFrom(null, new ConstraintFailList());
        $this->assertNull($ref->value());
    }
}
